// SPDX-License-Identifier: GPL-3.0
pragma solidity ^0.8.0;

contract PoseidonUnit2 {
    function poseidon(uint256[2] memory) public view returns (uint256) {}
}

contract PoseidonUnit3 {
    function poseidon(uint256[3] memory) public view returns (uint256) {}
}

contract Poseidon {
    PoseidonUnit2 _poseidonUnit2;
    PoseidonUnit3 _poseidonUnit3;

    constructor(address _poseidon2ContractAddr, address _poseidon3ContractAddr) {
        _poseidonUnit2 = PoseidonUnit2(_poseidon2ContractAddr);
        _poseidonUnit3 = PoseidonUnit3(_poseidon3ContractAddr);
    }

    function hash2(uint256[2] memory inp) public view returns (uint256) {
        return _poseidonUnit2.poseidon(inp);
    }

    function hash3(uint256[3] memory inp) public view returns (uint256) {
        return _poseidonUnit3.poseidon(inp);
    }
}

library PoseidonUnit1L {
    function poseidon(uint256[1] memory) public view returns (uint256) {}
}

library PoseidonUnit2L {
    function poseidon(uint256[2] memory) public view returns (uint256) {}
}

library PoseidonUnit3L {
    function poseidon(uint256[3] memory) public view returns (uint256) {}
}

library PoseidonUnit4L {
    function poseidon(uint256[4] memory) public view returns (uint256) {}
}

library PoseidonUnit5L {
    function poseidon(uint256[5] memory) public view returns (uint256) {}
}

library PoseidonUnit6L {
    function poseidon(uint256[6] memory) public view returns (uint256) {}
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.15;
pragma abicoder v2;

import "../libraries/Poseidon.sol";

/// @title A sparse merkle tree implementation, which keeps tree history.
// Note that this SMT implementation does not allow for duplicated roots in the history,
// which may be a critical restriction for some projects
library Smt {
    /**
     * @dev Max sparse merkle tree depth.
     * Note that we count the depth starting from 0, which is the root level.
     *
     * For example, the following tree has a MAX_SMT_DEPTH = 2:
     *
     *     O      <- root level (depth = 0)
     *    / \
     *   O   O    <- depth = 1
     *  / \ / \
     * O  O O  O  <- depth = 2
     */
    uint256 public constant MAX_SMT_DEPTH = 64;

    /**
     * @dev Max return array length for SMT root history requests
     */
    uint256 public constant SMT_ROOT_HISTORY_RETURN_LIMIT = 1000;

    /**
     * @dev Enum of SMT node types
     */
    enum NodeType {
        EMPTY,
        LEAF,
        MIDDLE
    }

    /**
     * @dev Sparse Merkle Tree data
     */
    struct SmtData {
        mapping(uint256 => Node) nodes;
        uint256[] rootHistory;
        mapping(uint256 => RootEntry) rootEntries;
        // This empty reserved space is put in place to allow future versions
        // of the SMT library to add new SmtData struct fields without shifting down
        // storage of upgradable contracts that use this struct as a state variable
        // (see https://docs.openzeppelin.com/upgrades-plugins/1.x/writing-upgradeable#storage-gaps)
        uint256[50] __gap;
    }

    /**
     * @dev Struct of the node proof in the SMT
     */
    struct Proof {
        uint256 root;
        bool existence;
        uint256[MAX_SMT_DEPTH] siblings;
        uint256 index;
        uint256 value;
        bool auxExistence;
        uint256 auxIndex;
        uint256 auxValue;
    }

    /**
     * @dev Struct for public interfaces to represent SMT root info.
     * @param root This SMT root.
     * @param replacedByRoot A root, which replaced this root.
     * @param createdAtTimestamp A time, when the root was saved to blockchain.
     * @param replacedAtTimestamp A time, when the root was replaced by the next root in blockchain.
     * @param createdAtBlock A number of block, when the root was saved to blockchain.
     * @param replacedAtBlock A number of block, when the root was replaced by the next root in blockchain.
     */
    struct RootInfo {
        uint256 root;
        uint256 replacedByRoot;
        uint256 createdAtTimestamp;
        uint256 replacedAtTimestamp;
        uint256 createdAtBlock;
        uint256 replacedAtBlock;
    }

    /**
     * @dev Struct for SMT root internal storage representation.
     * @param replacedByRoot A root, which replaced this root.
     * @param createdAtTimestamp A time, when the root was saved to blockchain.
     * @param createdAtBlock A number of block, when the root was saved to blockchain.
     */
    struct RootEntry {
        uint256 replacedByRoot;
        uint256 createdAtTimestamp;
        uint256 createdAtBlock;
    }

    /**
     * @dev Struct SMT node.
     * @param NodeType type of node.
     * @param childLeft left child of node.
     * @param childRight right child of node.
     * @param Index index of node.
     * @param Value value of node.
     */
    struct Node {
        NodeType nodeType;
        uint256 childLeft;
        uint256 childRight;
        uint256 index;
        uint256 value;
    }

    using BinarySearchSmtRoots for SmtData;

    /**
     * @dev Reverts if root does not exist in SMT roots history.
     * @param self SMT data.
     * @param root SMT root.
     */
    modifier onlyExistingRoot(SmtData storage self, uint256 root) {
        require(rootExists(self, root), "Root does not exist");
        _;
    }

    /**
     * @dev Add a node to the SMT
     * @param i Index of node
     * @param v Value of node
     */
    function add(SmtData storage self, uint256 i, uint256 v) public {
        Node memory node = Node(NodeType.LEAF, 0, 0, i, v);
        uint256 prevRoot = getRoot(self);
        uint256 newRoot = _addLeaf(self, node, prevRoot, 0);

        self.rootHistory.push(newRoot);

        self.rootEntries[newRoot].createdAtTimestamp = block.timestamp;
        self.rootEntries[newRoot].createdAtBlock = block.number;
        if (prevRoot != 0) {
            self.rootEntries[prevRoot].replacedByRoot = newRoot;
        }
    }

    /**
     * @dev Get SMT root history length
     * @return SMT history length
     */
    function getRootHistoryLength(
        SmtData storage self
    ) public view returns (uint256) {
        return self.rootHistory.length;
    }

    /**
     * @dev Get SMT root history
     * @param startIndex start index of history
     * @param length history length
     * @return array of RootInfo structs
     */
    function getRootHistory(
        SmtData storage self,
        uint256 startIndex,
        uint256 length
    ) public view returns (RootInfo[] memory) {
        require(length > 0, "Length should be greater than 0");
        require(
            length <= SMT_ROOT_HISTORY_RETURN_LIMIT,
            "History length limit exceeded"
        );

        uint256 endIndex = startIndex + length;
        require(
            endIndex <= self.rootHistory.length,
            "Out of bounds of root history"
        );

        RootInfo[] memory result = new RootInfo[](length);
        uint64 j = 0;
        for (uint256 i = startIndex; i < endIndex; i++) {
            uint256 root = self.rootHistory[i];
            result[j] = getRootInfo(self, root);
            j++;
        }
        return result;
    }

    function getNodeHash(Node memory node) internal view returns (uint256) {
        uint256 nodeHash;
        if (node.nodeType == NodeType.LEAF) {
            uint256[3] memory params = [node.index, node.value, uint256(1)];
            nodeHash = PoseidonUnit3L.poseidon(params);
        } else if (node.nodeType == NodeType.MIDDLE) {
            nodeHash = PoseidonUnit2L.poseidon(
                [node.childLeft, node.childRight]
            );
        }
        return nodeHash; // Note: expected to return 0 if NodeType.EMPTY, which is the only option left
    }

    /**
     * @dev Get the SMT node by hash
     * @param nodeHash Hash of a node
     * @return A node struct
     */
    function getNode(
        SmtData storage self,
        uint256 nodeHash
    ) public view returns (Node memory) {
        return self.nodes[nodeHash];
    }

    /**
     * @dev Get the proof if a node with specific index exists or not exists in the SMT
     * @param index Node index
     * @return Proof struct
     */
    function getProof(
        SmtData storage self,
        uint256 index
    ) public view returns (Proof memory) {
        return getProofByRoot(self, index, getRoot(self));
    }

    /**
     * @dev Get the proof if a node with specific index exists or not exists in the SMT for some historical tree state
     * @param index Node index
     * @param historicalRoot Historical SMT roof to get proof for
     * @return Proof struct
     */
    function getProofByRoot(
        SmtData storage self,
        uint256 index,
        uint256 historicalRoot
    )
        public
        view
        onlyExistingRoot(self, historicalRoot)
        returns (Proof memory)
    {
        Proof memory proof;
        proof.root = historicalRoot;
        proof.index = index;

        uint256 nextNodeHash = historicalRoot;
        Node memory node;

        for (uint256 i = 0; i <= MAX_SMT_DEPTH; i++) {
            node = getNode(self, nextNodeHash);
            if (node.nodeType == NodeType.EMPTY) {
                break;
            } else if (node.nodeType == NodeType.LEAF) {
                if (node.index == proof.index) {
                    proof.existence = true;
                    proof.value = node.value;
                    break;
                } else {
                    proof.auxExistence = true;
                    proof.auxIndex = node.index;
                    proof.auxValue = node.value;
                    proof.value = node.value;
                    break;
                }
            } else if (node.nodeType == NodeType.MIDDLE) {
                if ((proof.index >> i) & 1 == 1) {
                    nextNodeHash = node.childRight;
                    proof.siblings[i] = node.childLeft;
                } else {
                    nextNodeHash = node.childLeft;
                    proof.siblings[i] = node.childRight;
                }
            } else {
                revert("Invalid node type");
            }
        }
        return proof;
    }

    /**
     * @dev Get the proof if a node with specific index exists or not exists in the SMT for some historical timestamp
     * @param index Node index
     * @param timestamp The nearest timestamp to get proof for
     * @return Proof struct
     */
    function getProofByTime(
        SmtData storage self,
        uint256 index,
        uint256 timestamp
    ) public view returns (Proof memory) {
        RootInfo memory rootInfo = getRootInfoByTime(self, timestamp);

        require(rootInfo.root != 0, "historical root not found");

        return getProofByRoot(self, index, rootInfo.root);
    }

    /**
     * @dev Get the proof if a node with specific index exists or not exists in the SMT for some historical block number
     * @param index Node index
     * @param blockNumber The nearest block number to get proof for
     * @return Proof struct
     */
    function getProofByBlock(
        SmtData storage self,
        uint256 index,
        uint256 blockNumber
    ) public view returns (Proof memory) {
        RootInfo memory rootInfo = getRootInfoByBlock(self, blockNumber);

        require(rootInfo.root != 0, "historical root not found");

        return getProofByRoot(self, index, rootInfo.root);
    }

    function getRoot(SmtData storage self) public view returns (uint256) {
        return
            self.rootHistory.length > 0
                ? self.rootHistory[self.rootHistory.length - 1]
                : 0;
    }

    /**
     * @dev Binary search by timestamp
     * @param timestamp timestamp
     * return RootInfo struct
     */
    function getRootInfoByTime(
        SmtData storage self,
        uint256 timestamp
    ) public view returns (RootInfo memory) {
        require(timestamp <= block.timestamp, "errNoFutureAllowed");

        uint256 root = self.binarySearchUint256(
            timestamp,
            BinarySearchSmtRoots.SearchType.TIMESTAMP
        );

        return getRootInfo(self, root);
    }

    /**
     * @dev Binary search by block number
     * @param blockN block number
     * return RootInfo struct
     */
    function getRootInfoByBlock(
        SmtData storage self,
        uint256 blockN
    ) public view returns (RootInfo memory) {
        require(blockN <= block.number, "errNoFutureAllowed");

        uint256 root = self.binarySearchUint256(
            blockN,
            BinarySearchSmtRoots.SearchType.BLOCK
        );

        return getRootInfo(self, root);
    }

    /**
     * @dev Returns root info by root
     * @param root root
     * return RootInfo struct
     */
    function getRootInfo(
        SmtData storage self,
        uint256 root
    ) public view onlyExistingRoot(self, root) returns (RootInfo memory) {
        RootInfo memory rootInfo;
        rootInfo.createdAtTimestamp = self.rootEntries[root].createdAtTimestamp;
        rootInfo.createdAtBlock = self.rootEntries[root].createdAtBlock;
        rootInfo.replacedByRoot = self.rootEntries[root].replacedByRoot;
        rootInfo.replacedAtBlock = self
            .rootEntries[rootInfo.replacedByRoot]
            .createdAtBlock;
        rootInfo.replacedAtTimestamp = self
            .rootEntries[rootInfo.replacedByRoot]
            .createdAtTimestamp;
        rootInfo.root = root;

        return rootInfo;
    }

    /**
     * @dev Checks if root exists
     * @param root root
     * return true if root exists
     */
    function rootExists(
        SmtData storage self,
        uint256 root
    ) public view returns (bool) {
        return self.rootEntries[root].createdAtTimestamp > 0;
    }

    function _addLeaf(
        SmtData storage self,
        Node memory newLeaf,
        uint256 nodeHash,
        uint256 depth
    ) internal returns (uint256) {
        if (depth > MAX_SMT_DEPTH) {
            revert("Max depth reached");
        }

        Node memory node = self.nodes[nodeHash];
        uint256 nextNodeHash;
        uint256 leafHash;

        if (node.nodeType == NodeType.EMPTY) {
            leafHash = _addNode(self, newLeaf);
        } else if (node.nodeType == NodeType.LEAF) {
            leafHash = node.index == newLeaf.index
                ? _addNode(self, newLeaf)
                : _pushLeaf(
                    self,
                    newLeaf,
                    node,
                    depth,
                    newLeaf.index,
                    node.index
                );
        } else if (node.nodeType == NodeType.MIDDLE) {
            Node memory newNodeMiddle;

            if ((newLeaf.index >> depth) & 1 == 1) {
                nextNodeHash = _addLeaf(
                    self,
                    newLeaf,
                    node.childRight,
                    depth + 1
                );
                newNodeMiddle = Node(
                    NodeType.MIDDLE,
                    node.childLeft,
                    nextNodeHash,
                    0,
                    0
                );
            } else {
                nextNodeHash = _addLeaf(
                    self,
                    newLeaf,
                    node.childLeft,
                    depth + 1
                );
                newNodeMiddle = Node(
                    NodeType.MIDDLE,
                    nextNodeHash,
                    node.childRight,
                    0,
                    0
                );
            }

            leafHash = _addNode(self, newNodeMiddle);
        }

        return leafHash;
    }

    function _pushLeaf(
        SmtData storage self,
        Node memory newLeaf,
        Node memory oldLeaf,
        uint256 depth,
        uint256 pathNewLeaf,
        uint256 pathOldLeaf
    ) internal returns (uint256) {
        // no reason to continue if we are at max possible depth
        // as, anyway, we exceed the depth going down the tree
        if (depth >= MAX_SMT_DEPTH) {
            revert("Max depth reached");
        }

        Node memory newNodeMiddle;

        // Check if we need to go deeper if diverge at the depth's bit
        if ((pathNewLeaf >> depth) & 1 == (pathOldLeaf >> depth) & 1) {
            uint256 nextNodeHash = _pushLeaf(
                self,
                newLeaf,
                oldLeaf,
                depth + 1,
                pathNewLeaf,
                pathOldLeaf
            );

            if ((pathNewLeaf >> depth) & 1 == 1) {
                // go right
                newNodeMiddle = Node(NodeType.MIDDLE, 0, nextNodeHash, 0, 0);
            } else {
                // go left
                newNodeMiddle = Node(NodeType.MIDDLE, nextNodeHash, 0, 0, 0);
            }
            return _addNode(self, newNodeMiddle);
        }

        if ((pathNewLeaf >> depth) & 1 == 1) {
            newNodeMiddle = Node(
                NodeType.MIDDLE,
                getNodeHash(oldLeaf),
                getNodeHash(newLeaf),
                0,
                0
            );
        } else {
            newNodeMiddle = Node(
                NodeType.MIDDLE,
                getNodeHash(newLeaf),
                getNodeHash(oldLeaf),
                0,
                0
            );
        }

        _addNode(self, newLeaf);
        return _addNode(self, newNodeMiddle);
    }

    function _addNode(
        SmtData storage self,
        Node memory node
    ) internal returns (uint256) {
        uint256 nodeHash = getNodeHash(node);
        require(
            self.nodes[nodeHash].nodeType == NodeType.EMPTY,
            "Node already exists with the same index and value"
        );
        // We do not store empty nodes so can check if an entry exists
        self.nodes[nodeHash] = node;
        return nodeHash;
    }
}

/// @title A binary search for the sparse merkle tree root history
library BinarySearchSmtRoots {
    /**
     * @dev Enum for the SMT history field selection
     */
    enum SearchType {
        TIMESTAMP,
        BLOCK
    }

    function binarySearchUint256(
        Smt.SmtData storage self,
        uint256 value,
        SearchType searchType
    ) internal view returns (uint256) {
        if (self.rootHistory.length == 0) {
            return 0;
        }

        uint256 min = 0;
        uint256 max = self.rootHistory.length - 1;
        uint256 mid;
        uint256 midRoot;

        while (min <= max) {
            mid = (max + min) / 2;
            midRoot = self.rootHistory[mid];

            uint256 midValue = fieldSelector(
                self.rootEntries[midRoot],
                searchType
            );
            if (midValue == value) {
                while (mid < self.rootHistory.length - 1) {
                    uint256 nextRoot = self.rootHistory[mid + 1];
                    uint256 nextValue = fieldSelector(
                        self.rootEntries[nextRoot],
                        searchType
                    );
                    if (nextValue == value) {
                        mid++;
                        midRoot = nextRoot;
                    } else {
                        return midRoot;
                    }
                }
                return midRoot;
            } else if (value > midValue) {
                min = mid + 1;
            } else if (value < midValue && mid > 0) {
                // mid > 0 is to avoid underflow
                max = mid - 1;
            } else {
                // This means that value < midValue && mid == 0. So we return zero,
                // when search for a value less than the value in the first root
                return 0;
            }
        }

        // The case when the searched value does not exist and we should take the closest smaller value
        // Index in the "max" var points to the root with max value smaller than the searched value
        return self.rootHistory[max];
    }

    function fieldSelector(
        Smt.RootEntry memory rti,
        SearchType st
    ) internal pure returns (uint256) {
        if (st == SearchType.BLOCK) {
            return rti.createdAtBlock;
        } else if (st == SearchType.TIMESTAMP) {
            return rti.createdAtTimestamp;
        } else {
            revert("Invalid search type");
        }
    }
}

// SPDX-License-Identifier: GPL-3.0
pragma solidity 0.8.15;
pragma abicoder v2;

import "@openzeppelin/contracts-upgradeable/access/OwnableUpgradeable.sol";
import "../libraries/Smt.sol";
import "../libraries/Poseidon.sol";

interface IVerifier {
    function verifyProof(
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c,
        uint256[4] memory input
    ) external view returns (bool r);
}

/// @title Set and get states for each identity
contract StateV2 is OwnableUpgradeable {
    /**
     * @dev Max return array length for id history requests
     */
    uint256 public constant ID_HISTORY_RETURN_LIMIT = 1000;

    /**
     * @dev Struct for public interfaces to represent a state information.
     * @param id identity.
     * @param replacedByState A state, which replaced this state for the identity.
     * @param createdAtTimestamp A time when the state was created.
     * @param replacedAtTimestamp A time when the state was replaced by the next identity state.
     * @param createdAtBlock A block number when the state was created.
     * @param replacedAtBlock A block number when the state was replaced by the next identity state.
     */
    struct StateInfo {
        uint256 id;
        uint256 state;
        uint256 replacedByState;
        uint256 createdAtTimestamp;
        uint256 replacedAtTimestamp;
        uint256 createdAtBlock;
        uint256 replacedAtBlock;
    }

    /**
     * @dev Struct for identity state internal storage representation.
     * @param id An identity identifier.
     * @param timestamp A time when the state was committed to blockchain.
     * @param block A block number when the state was committed to blockchain.
     * @param replacedBy A state, which replaced this state for the identity.
     */
    struct StateEntry {
        uint256 id;
        uint256 timestamp;
        uint256 block;
        uint256 replacedBy;
    }

    /**
     * @dev Struct for storing all the state data
     * @param statesHistories A state history per each identity.
     * @param stateEntries A state metadata of each state
     */
    struct StateData {
        mapping(uint256 => uint256[]) statesHistories;
        mapping(uint256 => StateEntry) stateEntries;
        // This empty reserved space is put in place to allow future versions
        // of the State contract to add new SmtData struct fields without shifting down
        // storage of upgradable contracts that use this struct as a state variable
        // (see https://docs.openzeppelin.com/upgrades-plugins/1.x/writing-upgradeable#storage-gaps)
        uint256[50] __gap;
    }

    /**
     * @dev Verifier address
     */
    IVerifier internal verifier;

    /**
     * @dev State data
     */
    StateData internal _stateData;

    /**
     * @dev Global Identity State Tree (GIST) data
     */
    Smt.SmtData internal _gistData;
    using Smt for Smt.SmtData;

    /**
     * @dev event called when a state is updated
     * @param id identity
     * @param blockN Block number when the state has been committed
     * @param timestamp Timestamp when the state has been committed
     * @param state Identity state committed
     */
    event StateUpdated(
        uint256 id,
        uint256 blockN,
        uint256 timestamp,
        uint256 state
    );

    /**
     * @dev Revert if identity does not exist in the contract
     * @param id Identity
     */
    modifier onlyExistingId(uint256 id) {
        require(idExists(id), "Identity does not exist");
        _;
    }

    /**
     * @dev Revert if state does not exist in the contract
     * @param state State
     */
    modifier onlyExistingState(uint256 state) {
        require(stateExists(state), "State does not exist");
        _;
    }

    /**
     * @dev Initialize the contract
     * @param verifierContractAddr Verifier address
     */
    function initialize(IVerifier verifierContractAddr) public initializer {
        verifier = verifierContractAddr;
        __Ownable_init();
    }

    /**
     * @dev Set ZKP verifier contract address
     * @param newVerifierAddr Verifier contract address
     */
    function setVerifier(address newVerifierAddr) public onlyOwner {
        verifier = IVerifier(newVerifierAddr);
    }

    /**
     * @dev Change the state of an identity (transit to the new state) with ZKP ownership check.
     * @param id Identity
     * @param oldState Previous identity state
     * @param newState New identity state
     * @param isOldStateGenesis Is the previous state genesis?
     * @param a ZKP proof field
     * @param b ZKP proof field
     * @param c ZKP proof field
     */
    function transitState(
        uint256 id,
        uint256 oldState,
        uint256 newState,
        bool isOldStateGenesis,
        uint256[2] memory a,
        uint256[2][2] memory b,
        uint256[2] memory c
    ) public {
        if (isOldStateGenesis) {
            require(
                !idExists(id),
                "Old state is genesis but identity already exists"
            );
            require(!stateExists(oldState), "Genesis state already exists");
            // link genesis state to Id in the smart contract, but creation time and creation block is unknown
            _stateData.stateEntries[oldState].id = id;
            // push genesis state to identities as latest state
            _stateData.statesHistories[id].push(oldState);
        } else {
            require(
                idExists(id),
                "Old state is not genesis but identity does not yet exist"
            );

            uint256 previousIDState = _stateData.statesHistories[id][
                _stateData.statesHistories[id].length - 1
            ];

            require(
                _stateData.stateEntries[previousIDState].block != block.number,
                "No multiple set in the same block"
            );
            require(
                previousIDState == oldState,
                "Old state does not match the latest state"
            );
        }

        require(!stateExists(newState), "New state should not exist");

        uint256[4] memory input = [
            id,
            oldState,
            newState,
            uint256(isOldStateGenesis ? 1 : 0)
        ];
        require(
            verifier.verifyProof(a, b, c, input),
            "Zero-knowledge proof of state transition is not valid "
        );

        _stateData.statesHistories[id].push(newState);

        // Set create info for new state
        _stateData.stateEntries[newState] = StateEntry({
            id: id,
            timestamp: block.timestamp,
            block: block.number,
            replacedBy: 0
        });

        // Set replace info for old state
        _stateData.stateEntries[oldState].replacedBy = newState;

        // put state to GIST to recalculate global state
        _gistData.add(PoseidonUnit1L.poseidon([id]), newState);

        emit StateUpdated(id, block.number, block.timestamp, newState);
    }

    /**
     * @dev Get ZKP verifier contract address
     * @return verifier contract address
     */
    function getVerifier() public view returns (address) {
        return address(verifier);
    }

    /**
     * @dev Retrieve the last state info for a given identity
     * @param id identity
     * @return state info of the last committed state
     */
