pragma solidity ^0.8.13;

import {ERC20} from "solmate/tokens/ERC20.sol";

contract BatchTokenTransfers{
    ERC20 immutable public WLD_TOKEN;
    // TxSitter Relayer is the only one that can call the batch function
    address immutable public owner;
    // BVI wallet that grants allowances to this contract
    address immutable public holder;

    constructor(address _wld_token_address, address _holder, address _owner) {
        WLD_TOKEN = ERC20(_wld_token_address);
        holder = _holder;
        owner = _owner;
    }

    modifier onlyOwner() {
        require(msg.sender == owner, "BatchTokenTransfers: ONLY_OWNER");
        _;
    }

    function batch(
        address[] calldata _recipients,
        uint256[] calldata _amounts
    ) onlyOwner external {
        require(
            _recipients.length == _amounts.length,
            "BatchTokenTransfers: LENGTH_MISMATCH"
        );

        for (uint256 i = 0; i < _recipients.length; i++) {
            require(WLD_TOKEN.transferFrom(holder, _recipients[i], _amounts[i]));
        }
    }
}

